//! S02 contract battery: ownership map and coverage partition over the pinned
//! mixed WordML fixture, read through the frozen `source_package` substrate.
//!
//! The per-view fragment lists below are a **handwritten oracle** derived from
//! `fixtures/reader/mixed-wordml.xml` (never generated by the code under test).
//! Element ids are the substrate's pre-order `eN` scheme; every id is annotated
//! with the XML path it came from. The fixture is pinned by sha256.

use std::collections::HashSet;

use ln_decode::reader_contract::{
    check_fragment_span, control_derived_kind, partition_primary_views, reference_type_of,
    role_of_tag, tail_view_key, view_key, whole_fragment_span, ContractErrorKind, ElementRef,
    FragmentRef, PartitionReport, PrimaryOwnership, ReaderDerivedKind, ReaderFragmentSpan,
    ReaderRecordIndex, ReaderReferenceType, ReaderRole, ReaderSegmentKind, ReaderSemantic,
    ReaderViewKey, ReaderViewKind,
};
use ln_decode::source_package::{capture, Limits, TextSlot};

const XML: &str = include_str!("fixtures/reader/mixed-wordml.xml");
const FIXTURE_SHA256: &str = "d2fc1cd17f0697f575e94f09d83da5027d73afd37c700772eafa4c4a4fbc76db";

fn index() -> ReaderRecordIndex {
    let package = capture(XML.as_bytes(), &Limits::default()).expect("fixture must capture");
    assert_eq!(
        package.manifest().source.sha256,
        FIXTURE_SHA256,
        "fixture content changed; re-pin FIXTURE_SHA256 and the handwritten oracle"
    );
    ReaderRecordIndex::new(package.records()).expect("records must index")
}

fn value_of(index: &ReaderRecordIndex, fragment: &str) -> String {
    index
        .text(fragment)
        .expect("fragment must exist")
        .value
        .clone()
}

fn values_for(
    index: &ReaderRecordIndex,
    report: &PartitionReport,
    key: &ReaderViewKey,
) -> Vec<String> {
    report
        .fragments_for(key)
        .iter()
        .map(|fragment| value_of(index, fragment.as_str()))
        .collect()
}

fn para(id: &str) -> ReaderViewKey {
    ReaderViewKey::new(ReaderViewKind::Paragraph, ElementRef::from(id))
}

fn residual(id: &str) -> ReaderViewKey {
    ReaderViewKey::new(ReaderViewKind::Residual, ElementRef::from(id))
}

#[test]
fn fixture_has_element_and_text_records() {
    let index = index();
    assert!(
        index.elements().len() >= 20,
        "expected a mixed document, got {} elements",
        index.elements().len()
    );
    assert_eq!(index.texts().len(), 15, "handwritten tN count");
    for text in index.texts() {
        assert!(!text.value.is_empty(), "{} must carry text", text.id);
    }
}

#[test]
fn coverage_partition_is_total_and_duplicate_free() {
    let index = index();
    let report = partition_primary_views(&index).expect("partition must build");
    assert_eq!(report.len(), index.texts().len());
    assert!(report.duplicates().is_empty(), "no duplicate fragment");
    assert!(report.dangling(&index).is_empty(), "no dangling fragment");
    assert!(report.missing(&index).is_empty(), "no missing fragment");
    report.check(&index).expect("partition must be complete");

    let mut seen: HashSet<String> = HashSet::new();
    for entry in &report.entries {
        assert!(
            seen.insert(entry.fragment.as_str().to_string()),
            "fragment {} owned twice",
            entry.fragment
        );
    }
}

#[test]
fn handwritten_oracle_per_view() {
    let index = index();
    let report = partition_primary_views(&index).expect("partition must build");

    // e0 wordDocument; e1 body; e2 p(Alpha); e5 p(Beta, tab, instrText PAGE);
    // e10 tbl; e11 tr; e12 tc; e13 p(Gamma); e16 r(Delta) sibling after e13;
    // e18 tc; e19 p(Epsilon, br, br@page); e24 p(Zeta, Eta); e29 p(Theta, Iota);
    // e35 unknownThing(Kappa); e37 foreign(Lambda); e38 p(NBSP); e42 footnote;
    // e43 p(Nu).
    let expected: [(ReaderViewKey, Vec<&str>); 11] = [
        (para("e2"), vec!["Alpha"]),
        (para("e5"), vec!["Beta", "PAGE"]),
        (para("e13"), vec!["Gamma"]),
        (residual("e13"), vec![" "]),
        (residual("e16"), vec!["Delta"]),
        (para("e19"), vec!["Epsilon"]),
        (para("e24"), vec!["Zeta", "Eta"]),
        (para("e29"), vec!["Theta", "Iota"]),
        (residual("e0"), vec!["Kappa", "Lambda"]),
        (para("e38"), vec!["NBSP:\u{00A0}Mu"]),
        (para("e43"), vec!["Nu"]),
    ];

    let mut covered = 0;
    for (key, values) in expected {
        assert_eq!(values_for(&index, &report, &key), values, "view {key:?}");
        covered += values.len();
    }
    assert_eq!(covered, 15, "oracle must cover every text record");
}

#[test]
fn element_roles_match_the_contract() {
    let index = index();
    let expected = [
        ("e2", ReaderRole::Paragraph),
        ("e5", ReaderRole::Paragraph),
        ("e8", ReaderRole::Control),
        ("e9", ReaderRole::Field),
        ("e10", ReaderRole::Table),
        ("e11", ReaderRole::Row),
        ("e12", ReaderRole::Cell),
        ("e13", ReaderRole::Paragraph),
        ("e18", ReaderRole::Cell),
        ("e19", ReaderRole::Paragraph),
        ("e21", ReaderRole::Control),
        ("e22", ReaderRole::Control),
        ("e24", ReaderRole::Paragraph),
        ("e26", ReaderRole::Field),
        ("e29", ReaderRole::Paragraph),
        ("e31", ReaderRole::RevisionInsertion),
        ("e33", ReaderRole::RevisionDeletion),
        ("e35", ReaderRole::Unknown),
        ("e37", ReaderRole::Foreign),
        ("e38", ReaderRole::Paragraph),
        ("e41", ReaderRole::NoteReference),
        ("e42", ReaderRole::Note),
        ("e43", ReaderRole::Paragraph),
        ("e46", ReaderRole::NoteReference),
    ];
    for (id, role) in expected {
        assert_eq!(index.role_of(id), Some(role), "role of {id}");
    }
}

#[test]
fn controls_are_derived_and_have_no_source_fragment() {
    let index = index();
    let expected = [
        ("e8", ReaderDerivedKind::Tab),
        ("e21", ReaderDerivedKind::LineBreak),
        ("e22", ReaderDerivedKind::PageBreak),
    ];
    for (id, kind) in expected {
        let element = index.element(id).expect("control element");
        assert_eq!(index.role_of(id), Some(ReaderRole::Control), "{id} role");
        assert_eq!(
            control_derived_kind(&element.clark_tag, &element.attrs),
            Some(kind),
            "{id} derived kind"
        );
        assert!(
            element.text_ref.is_none(),
            "{id} must not own a text fragment"
        );
        assert!(
            element.tail_ref.is_none(),
            "{id} must not own a tail fragment"
        );
    }
    // A foreign-namespaced element is never rendered as a control.
    let foreign = index.element("e37").expect("foreign element");
    assert_eq!(
        control_derived_kind(&foreign.clark_tag, &foreign.attrs),
        None
    );
}

#[test]
fn every_text_record_has_a_valid_whole_fragment_span() {
    let index = index();
    for text in index.texts() {
        let fragment = FragmentRef::from(text.id.as_str());
        let span = whole_fragment_span(&fragment, &text.value);
        assert_eq!(span.start, 0);
        assert_eq!(span.end, text.value.len());
        check_fragment_span(&text.value, &span).expect("valid whole-fragment span");
        assert_eq!(text.bytes, text.value.len() as u64, "{} bytes", text.id);
        assert_eq!(text.chars, text.value.chars().count() as u64);
    }
}

#[test]
fn unknown_and_foreign_are_references_not_primary_views() {
    let index = index();
    let report = partition_primary_views(&index).expect("partition must build");
    let unknown = index.element("e35").expect("unknown element");
    let foreign = index.element("e37").expect("foreign element");

    assert_eq!(index.role_of("e35"), Some(ReaderRole::Unknown));
    assert_eq!(index.role_of("e37"), Some(ReaderRole::Foreign));
    assert_eq!(role_of_tag(&unknown.clark_tag), ReaderRole::Unknown);
    assert_eq!(role_of_tag(&foreign.clark_tag), ReaderRole::Foreign);
    assert_eq!(
        reference_type_of(&unknown.clark_tag, &unknown.attrs),
        Some(ReaderReferenceType::UnknownWordmlElement)
    );
    assert_eq!(
        reference_type_of(&foreign.clark_tag, &foreign.attrs),
        Some(ReaderReferenceType::ForeignElement)
    );

    for anchor in ["e35", "e37"] {
        assert!(
            !report
                .entries
                .iter()
                .any(|entry| entry.view.element_ref.as_str() == anchor),
            "{anchor} must not anchor a primary view"
        );
    }

    // Text nested in the unknown/foreign subtree still gets a primary owner:
    // no paragraph ancestor, so both are residual-anchored at the document root.
    assert_eq!(
        view_key(&index, &ElementRef::from("e36")).unwrap(),
        residual("e0")
    );
    assert_eq!(
        values_for(&index, &report, &residual("e0")),
        vec!["Kappa", "Lambda"]
    );
}

#[test]
fn references_classify_as_typed_unresolved() {
    let index = index();
    let expected = [
        ("e9", ReaderReferenceType::Field),
        ("e26", ReaderReferenceType::Field),
        ("e41", ReaderReferenceType::NoteReference),
        ("e46", ReaderReferenceType::NoteReference),
    ];
    for (id, reference_type) in expected {
        let element = index.element(id).expect("reference element");
        assert_eq!(
            reference_type_of(&element.clark_tag, &element.attrs),
            Some(reference_type),
            "{id}"
        );
    }
    // A structural paragraph is not a reference.
    let paragraph = index.element("e13").expect("paragraph");
    assert_eq!(
        reference_type_of(&paragraph.clark_tag, &paragraph.attrs),
        None
    );
}

#[test]
fn tail_of_a_paragraph_inside_a_cell_is_a_cell_level_residual() {
    let index = index();
    // e13 is the paragraph in the first cell; its tail is the single space
    // before the sibling run, so it stays a residual anchored at e13.
    assert_eq!(
        tail_view_key(&index, &ElementRef::from("e13")).unwrap(),
        residual("e13")
    );
    // A tail of a run inside a paragraph belongs to the parent paragraph.
    assert_eq!(
        tail_view_key(&index, &ElementRef::from("e3")).unwrap(),
        para("e2")
    );
}

#[test]
fn unknown_wire_tokens_fail_closed() {
    assert_eq!(
        ReaderViewKind::from_wire("Paragraph").unwrap_err().kind(),
        ContractErrorKind::UnknownToken
    );
    assert_eq!(
        ReaderSegmentKind::from_wire("source").unwrap_err().kind(),
        ContractErrorKind::UnknownToken
    );
    assert_eq!(
        ReaderDerivedKind::from_wire("pageBreak")
            .unwrap_err()
            .kind(),
        ContractErrorKind::UnknownToken
    );
    assert_eq!(
        ReaderSemantic::from_wire("sep").unwrap_err().kind(),
        ContractErrorKind::UnknownToken
    );
    assert_eq!(
        ReaderReferenceType::from_wire("inert_payload")
            .unwrap_err()
            .kind(),
        ContractErrorKind::UnknownToken
    );
}

#[test]
fn span_negatives_are_typed_errors() {
    let value = "Привет";
    let fragment = FragmentRef::from("t0");
    assert_eq!(
        check_fragment_span(value, &ReaderFragmentSpan::new(fragment.clone(), 3, 1))
            .unwrap_err()
            .kind(),
        ContractErrorKind::EmptyOrInverted
    );
    assert_eq!(
        check_fragment_span(
            value,
            &ReaderFragmentSpan::new(fragment.clone(), 0, value.len() + 1)
        )
        .unwrap_err()
        .kind(),
        ContractErrorKind::OutOfBounds
    );
    assert_eq!(
        check_fragment_span(value, &ReaderFragmentSpan::new(fragment, 1, 3))
            .unwrap_err()
            .kind(),
        ContractErrorKind::NotCharBoundary
    );
}

#[test]
fn partition_negatives_fail_closed() {
    let index = index();
    let report = partition_primary_views(&index).expect("partition must build");

    let mut duplicate = report.clone();
    duplicate.entries.push(duplicate.entries[0].clone());
    assert_eq!(duplicate.duplicates().len(), 1);
    assert_eq!(
        duplicate.check(&index).unwrap_err().kind(),
        ContractErrorKind::PartitionIncomplete
    );

    let mut missing = report.clone();
    missing.entries.pop();
    assert_eq!(missing.missing(&index).len(), 1);
    assert!(missing.check(&index).is_err());

    let mut dangling = report.clone();
    dangling.entries.push(PrimaryOwnership {
        fragment: FragmentRef::from("t404"),
        slot: TextSlot::Text,
        view: residual("e0"),
    });
    assert_eq!(dangling.dangling(&index).len(), 1);
    assert!(dangling.check(&index).is_err());
}
